namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Abbreviation { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
        new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
        new() { Id = 3, Name = "English", Abbreviation = "ENG" },
        new() { Id = 4, Name = "Physics", Abbreviation = "PHYS" },
        new() { Id = 5, Name = "History", Abbreviation = "HIST" },
    ];

    private readonly List<Course> _courses;

    public CatalogService()
    {
        _courses =
        [
            new()
            {
                Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming",
                Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented design.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM",
                InstructorName = "Dr. Sarah Chen",
                InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT.",
                DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true
            },
            new()
            {
                Id = 2, CourseCode = "CS 201", Title = "Data Structures and Algorithms",
                Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques.",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM",
                InstructorName = "Dr. James Park",
                InstructorBio = "Dr. Park specializes in algorithm optimization and has published over 40 papers in top-tier conferences.",
                DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true
            },
            new()
            {
                Id = 3, CourseCode = "CS 301", Title = "Database Systems",
                Description = "Design and implementation of relational databases, SQL, normalization, and transaction management.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM",
                InstructorName = "Dr. Maria Lopez",
                InstructorBio = "Dr. Lopez worked at Oracle for a decade before joining academia. She focuses on distributed database systems.",
                DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false
            },
            new()
            {
                Id = 4, CourseCode = "MATH 101", Title = "Calculus I",
                Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM",
                InstructorName = "Prof. Alan Wright",
                InstructorBio = "Prof. Wright has taught calculus for over 20 years and authored two widely-used textbooks.",
                DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true
            },
            new()
            {
                Id = 5, CourseCode = "MATH 201", Title = "Linear Algebra",
                Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM",
                InstructorName = "Dr. Emily Nguyen",
                InstructorBio = "Dr. Nguyen's research focuses on applied linear algebra in machine learning applications.",
                DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false
            },
            new()
            {
                Id = 6, CourseCode = "ENG 101", Title = "Composition and Rhetoric",
                Description = "Develop critical reading, thinking, and writing skills. Emphasis on argument construction and essay writing.",
                Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM",
                InstructorName = "Prof. David Miller",
                InstructorBio = "Prof. Miller is a published author and has taught writing at the university level for 12 years.",
                DepartmentId = 3, DepartmentName = "English", IsFeatured = false
            },
            new()
            {
                Id = 7, CourseCode = "ENG 205", Title = "American Literature",
                Description = "Survey of American literature from the colonial period to the present, including major movements and authors.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM",
                InstructorName = "Dr. Rachel Green",
                InstructorBio = "Dr. Green specializes in 20th-century American fiction and has received multiple teaching awards.",
                DepartmentId = 3, DepartmentName = "English", IsFeatured = true
            },
            new()
            {
                Id = 8, CourseCode = "PHYS 101", Title = "General Physics I",
                Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions.",
                Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM",
                InstructorName = "Dr. Robert Kim",
                InstructorBio = "Dr. Kim is an experimental physicist with research interests in condensed matter physics.",
                DepartmentId = 4, DepartmentName = "Physics", IsFeatured = false
            },
            new()
            {
                Id = 9, CourseCode = "PHYS 201", Title = "Electromagnetism",
                Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.",
                Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:15 PM",
                InstructorName = "Dr. Lisa Wang",
                InstructorBio = "Dr. Wang's research in photonics has been featured in Nature and Science magazines.",
                DepartmentId = 4, DepartmentName = "Physics", IsFeatured = false
            },
            new()
            {
                Id = 10, CourseCode = "HIST 101", Title = "World History to 1500",
                Description = "Survey of major civilizations and events from antiquity through the late medieval period.",
                Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM",
                InstructorName = "Prof. Thomas Brown",
                InstructorBio = "Prof. Brown is a medieval historian who has conducted excavations across Europe and the Middle East.",
                DepartmentId = 5, DepartmentName = "History", IsFeatured = false
            },
            new()
            {
                Id = 11, CourseCode = "HIST 202", Title = "Modern World History",
                Description = "Political, social, and economic developments from the Enlightenment to the present day.",
                Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM",
                InstructorName = "Dr. Angela Davis",
                InstructorBio = "Dr. Davis focuses on 20th-century geopolitics and is a frequent commentator for historical documentaries.",
                DepartmentId = 5, DepartmentName = "History", IsFeatured = true
            },
        ];
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

