            <h5>Schedule</h5>
            <p>@_course.Schedule</p>

            <h5>Credits</h5>
            <p>@_course.Credits</p>

            <h5>Department</h5>
            <p><a href="/courses?departmentId=@_course.DepartmentId">@_course.DepartmentName</a></p>
        </div>
        <div class="col-lg-4">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Instructor</h5>
