@page "/"

@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Home - University Course Catalog</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-5 fw-bold">Welcome to the University Course Catalog</h1>
    <p class="lead text-muted">Browse departments, explore courses, and submit your enrollment request.</p>
    <a href="/courses" class="btn btn-primary btn-lg me-2">Browse Courses</a>
    <a href="/enroll" class="btn btn-outline-primary btn-lg">Enroll Now</a>
</div>

<section class="mb-5">
    <h2>Featured Courses</h2>
    <div class="row">
        @foreach (var course in _featuredCourses)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@course.CourseCode</h5>
                        <h6 class="card-subtitle mb-2 text-muted">@course.Title</h6>
                        <p class="card-text small">@course.Credits credits · @course.DepartmentName</p>
                        <a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>
</section>

<section>
    <h2>Departments</h2>
    <div class="row">
        @foreach (var dept in _departments)
        {
            <div class="col-md-4 col-lg-3 mb-3">
                <a href="/courses?departmentId=@dept.Id" class="text-decoration-none">
                    <div class="card text-center p-3 h-100">
                        <h5 class="mb-1">@dept.Abbreviation</h5>
                        <p class="text-muted mb-0 small">@dept.Name</p>
                    </div>
                </a>
            </div>
        }
    </div>
</section>

@code {
    private List<Course> _featuredCourses = [];
    private List<Department> _departments = [];

    protected override void OnInitialized()
    {
        _featuredCourses = Catalog.GetFeaturedCourses();
        _departments = Catalog.GetDepartments();
    }
}

